#include <array>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>

int main() {
    std::array<std::int32_t, 3> readings{1, 256, -1};
    {
        std::ofstream out{"readings.bin", std::ios::binary};
        out.write(reinterpret_cast<const char*>(readings.data()),
                  sizeof(readings));
    }
    auto size{std::filesystem::file_size("readings.bin")};
    std::cout << "file size: " << size << " bytes\n";

    std::ifstream in{"readings.bin", std::ios::binary};
    char byte{};
    int i{0};
    while (in.get(byte)) {
        std::cout << std::hex << std::setw(2) << std::setfill('0')
                  << (static_cast<int>(byte) & 0xFF) << ' ';
        if (++i % 4 == 0) std::cout << '\n';
    }

    in.clear();
    in.seekg(0);
    std::array<std::int32_t, 3> back{};
    in.read(reinterpret_cast<char*>(back.data()), sizeof(back));
    std::cout << std::dec << "read back: " << back[0] << ' '
              << back[1] << ' ' << back[2] << '\n';
}

