#include <stdexcept>
#include <string>
#include <vector>

using Tools = std::vector<std::string>;

void label_all(Tools& tools, const std::string& tag) {
    Tools draft{tools};
    for (std::string& t : draft) {
        if (t.empty()) throw std::invalid_argument{"no name"};
        t = tag + t;
    }
    tools.swap(draft);
}

void show(const Tools& tools) {
    for (const std::string& t : tools) std::cout << '[' << t << ']';
    std::cout << '\n';
}

int main() {
    Tools tools{"saw", "", "drill"};
    try {
        label_all(tools, "W-");
    } catch (const std::exception& e) {
        std::cout << "refused: " << e.what() << '\n';
    }
    show(tools);
    tools.erase(tools.begin() + 1);
    label_all(tools, "W-");
    show(tools);
}

