struct GaugeError : std::runtime_error {
    using std::runtime_error::runtime_error;
};
struct TooHot : GaugeError {
    using GaugeError::GaugeError;
};

void check(int temp) {
    if (temp > 90) throw TooHot{"too hot"};
    if (temp < 0) throw GaugeError{"sensor fault"};
}

int main() {
    for (int t : {50, 120, -5}) {
        try {
            check(t);
            std::cout << t << " ok\n";
        } catch (const TooHot& e) {
            std::cout << t << ' ' << e.what() << " code "
                      << std::hex << 255 << '\n';
        } catch (const GaugeError& e) {
            std::cout << t << ' ' << e.what() << '\n';
        }
    }
}

