#include <iostream>
#include <stdexcept>
#include <string>

class WorkshopError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

class PartMissing : public WorkshopError {
public:
    PartMissing(const std::string& part, int bin)
        : WorkshopError{"no " + part + " in bin "
                        + std::to_string(bin)},
          bin_{bin} {}
    int bin() const { return bin_; }
private:
    int bin_;
};

class ToolBroken : public WorkshopError {
public:
    using WorkshopError::WorkshopError;
};

void job(int n) {
    if (n == 1) throw PartMissing{"bolt", 7};
    if (n == 2) throw ToolBroken{"wrench snapped"};
    if (n == 3) throw std::runtime_error{"power cut"};
    std::cout << "job " << n << ": done\n";
}

int main() {
    for (int n = 0; n <= 3; ++n) {
        try {
            job(n);
        } catch (const PartMissing& e) {
            std::cout << "job " << n << ": " << e.what()
                      << " (reorder bin " << e.bin() << ")\n";
        } catch (const WorkshopError& e) {
            std::cout << "job " << n << ": workshop: "
                      << e.what() << '\n';
        } catch (const std::exception& e) {
            std::cout << "job " << n << ": other: " << e.what() << '\n';
        }
    }
}

