trace_guarantee.cpp.src:
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

void add_basic(std::vector<std::string>& v, const std::string& a,
               const std::string& b) {
    v.push_back(a);
    if (b.empty()) throw std::invalid_argument{"no name"};
    v.push_back(b);
}

void add_strong(std::vector<std::string>& v, const std::string& a,
                const std::string& b) {
    std::vector<std::string> draft{v};
    draft.push_back(a);
    if (b.empty()) throw std::invalid_argument{"no name"};
    draft.push_back(b);
    v.swap(draft);
}

int main() {
    std::vector<std::string> v;
    std::string calls[4]{"basic", "strong", "basic", "strong"};
    std::string seconds[4]{"nut", "", "", "pin"};
    for (int i = 0; i < 4; ++i) {
        std::string result{"ok"};
        try {
            if (calls[i] == "basic") add_basic(v, "x", seconds[i]);
            else add_strong(v, "x", seconds[i]);
        } catch (const std::exception&) {
            result = "threw";
        }
        std::cout << calls[i] << ' ' << result << ' ' << v.size() << '\n';
    }
}

